/* Generated from the ROM's code by build/re/tools/z80prog.py (not in the
   repository), then read. */
#include "sim/progs.h"

/* each instruction a case of the switch, falling into the next */
#if defined(__clang__)
#pragma clang diagnostic ignored "-Wimplicit-fallthrough"
#elif defined(__GNUC__)
#pragma GCC diagnostic ignored "-Wimplicit-fallthrough"
#endif

/* An instruction: a place to go on from, where the program stops once its
   cycles reach its budget (z->pc then where it goes on). I0: one fetch, no
   other access; IF: fetches after its first (prefixes, operands), at the
   offsets given, where its slice can end too; I: its length and its data
   accesses' offsets, checked when it would end past the budget (or is
   being run again); IA: both. IL0, ILF, IL, ILA: a jump's target too. */
#define STOP(n)                                                                                                        \
    if (z->t >= z->budget) {                                                                                           \
        z->pc = 0x##n;                                                                                                 \
        return;                                                                                                        \
    }
#define FETCH(n, len, fo) if (z->t + (len) > z->limit) cpu_fetch(z, 0x##n, fo);
#define ACCESS(n, len, offs)                                                                                           \
    if (z->stopped || z->t + (len) > z->limit) cpu_part(z, 0x##n, offs);                                               \
    else cpu_insn(z, offs);
#define I0(n) case 0x##n: STOP(n) z->partial = 0; z->offs = 0;
#define IL0(n) case 0x##n: x##n: STOP(n) z->partial = 0; z->offs = 0;
#define IF(n, len, fo) case 0x##n: STOP(n) FETCH(n, len, fo) z->stopped = 0; z->partial = 0; z->offs = 0;
#define ILF(n, len, fo) case 0x##n: x##n: STOP(n) FETCH(n, len, fo) z->stopped = 0; z->partial = 0; z->offs = 0;
#define I(n, len, offs) case 0x##n: STOP(n) ACCESS(n, len, offs)
#define IL(n, len, offs) case 0x##n: x##n: STOP(n) ACCESS(n, len, offs)
#define IA(n, len, offs, fo) case 0x##n: STOP(n) FETCH(n, len, fo) ACCESS(n, len, offs)
#define ILA(n, len, offs, fo) case 0x##n: x##n: STOP(n) FETCH(n, len, fo) ACCESS(n, len, offs)

